  "trends.sourceLabel": "మూలం: {domain}",
  "trends.item1.title": "యూరోపియన్ సమ్మర్ కలెక్షన్‌లో అజ్రఖ్ మరియు ఎర్త్ టోన్స్",
  "trends.item1.desc": "సహజ రంగులు మరియు బోటిక్ డిమాండ్‌లో పెరుగుతున్న దుస్తులు.",
  "trends.item1.curator": "మీరా రావు (మంత్రిత్వ శాఖ సోర్సింగ్ సలహాదారు)",
  "trends.item2.title": "ఖాదీ పండుగ దుస్తులపై సమకాలీన జర్దోజీ బోర్డర్",
  "trends.item2.desc": "ఖాదీ దుస్తులపై జర్దోజీ బోర్డర్ల పెరుగుతున్న డిమాండ్.",
